    /// <summary>
    /// Returns the minimum and maximum values in <paramref name="values"/>.
    /// Uses SIMD vectorization for high throughput on large spans.
    /// </summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static (float Min, float Max) FindMinMax(ReadOnlySpan<float> values)
    {
        if (values.Length == 0)
            throw new ArgumentException("Span must not be empty.");

        ref float start = ref MemoryMarshal.GetReference(values);

        if (Vector512.IsHardwareAccelerated && values.Length >= Vector512<float>.Count * 2)
        {
            return FindMinMaxVector512(ref start, values.Length);
        }

        if (Vector256.IsHardwareAccelerated && values.Length >= Vector256<float>.Count * 2)
        {
            return FindMinMaxVector256(ref start, values.Length);
        }

        if (Vector128.IsHardwareAccelerated && values.Length >= Vector128<float>.Count * 2)
        {
            return FindMinMaxVector128(ref start, values.Length);
        }

        return FindMinMaxScalar(ref start, values.Length);
    }

    private static (float Min, float Max) FindMinMaxVector512(ref float start, int length)
    {
        int count = Vector512<float>.Count;
        var vMin = Vector512.LoadUnsafe(ref start);
        var vMax = vMin;

        int i = count;
        int limit = length - (count * 4 - 1);

        // Process 4 vectors per iteration to improve ILP
        for (; i < limit; i += count * 4)
        {
            var v0 = Vector512.LoadUnsafe(ref start, (nuint)i);
            var v1 = Vector512.LoadUnsafe(ref start, (nuint)(i + count));
            var v2 = Vector512.LoadUnsafe(ref start, (nuint)(i + count * 2));
            var v3 = Vector512.LoadUnsafe(ref start, (nuint)(i + count * 3));

            var min01 = Vector512.Min(v0, v1);
            var min23 = Vector512.Min(v2, v3);
            vMin = Vector512.Min(vMin, Vector512.Min(min01, min23));

            var max01 = Vector512.Max(v0, v1);
            var max23 = Vector512.Max(v2, v3);
            vMax = Vector512.Max(vMax, Vector512.Max(max01, max23));
        }

        for (; i <= length - count; i += count)
        {
            var v = Vector512.LoadUnsafe(ref start, (nuint)i);
            vMin = Vector512.Min(vMin, v);
            vMax = Vector512.Max(vMax, v);
        }

        // Reduce 512 -> scalar
        var lo256 = vMin.GetLower();
        var hi256 = vMin.GetUpper();
        var min256 = Vector256.Min(lo256, hi256);
        var loMin = min256.GetLower();
        var hiMin = min256.GetUpper();
        var min128 = Vector128.Min(loMin, hiMin);

        lo256 = vMax.GetLower();
        hi256 = vMax.GetUpper();
        var max256 = Vector256.Max(lo256, hi256);
        var loMax = max256.GetLower();
        var hiMax = max256.GetUpper();
        var max128 = Vector128.Max(loMax, hiMax);

        float min = HorizontalMin(min128);
        float max = HorizontalMax(max128);

        // Handle remaining elements
        for (; i < length; i++)
        {
            float val = Unsafe.Add(ref start, i);
            if (val < min) min = val;
            if (val > max) max = val;
        }

        return (min, max);
    }

